{
  "title": "TB Transmission Learning Game",
  "perWatchSecond": 0.5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Eliminate TB by cutting contact",
      "goal": "Show that lowering the contact rate can drive infections toward zero.",
      "control": {
        "parameter": "beta",
        "label": "Contact rate",
        "lowEnd": "3.0e-7",
        "highEnd": "1.0e-6"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if the contact rate is halved?",
        "parameter": "beta",
        "value": 3.875e-7
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 38,
        "relation": "lower",
        "by": 5000000
      },
      "effect": "Halving the contact rate lowers the infectious peak by more than five million.",
      "prediction": {
        "prompt": "Predict the infectious peak in the what‑if world.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Headline result",
        "quote": "The model shows that TB can be eliminated if the reproduction number is kept below one."
      },
      "carryForward": "Next we examine how treatment speed changes the outbreak."
    },
    {
      "kind": "background",
      "finding": 2,
      "title": "Treat faster, cases drop",
      "goal": "Demonstrate that increasing treatment rate reduces infectious cases.",
      "control": {
        "parameter": "delta",
        "label": "Treatment rate",
        "lowEnd": "0.3",
        "highEnd": "1.3"
      },
      "watch": "Infectious peak (i)",
      "whatIf": {
        "prompt": "What if the treatment rate is doubled?",
        "parameter": "delta",
        "value": 1.34
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 38,
        "relation": "lower",
        "by": 4500000
      },
      "effect": "Doubling the treatment rate lowers the infectious peak by about 4.5 million.",
      "prediction": {
        "prompt": "Will the infectious peak be higher or lower?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Treatment effect",
        "quote": "Increasing the treatment rate for infectious individuals significantly reduces the number of cases and could eventually eliminate TB locally."
      },
      "carryForward": "Now we look at how faster progression from exposure affects the epidemic."
    },
    {
      "kind": "idea",
      "finding": 3,
      "title": "Progression speed drives spread",
      "goal": "Show that a higher progression rate from exposed to infectious raises cases.",
      "control": {
        "parameter": "gamma",
        "label": "Progression rate",
        "lowEnd": "0.1",
        "highEnd": "0.45"
      },
      "watch": "Infectious peak (i)",
      "whatIf": {
        "prompt": "What if the progression rate is doubled?",
        "parameter": "gamma",
        "value": 0.45
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 38,
        "relation": "higher",
        "by": 7300000
      },
      "effect": "Doubling the progression rate raises the infectious peak by about 7.3 million.",
      "prediction": {
        "prompt": "Will the infectious peak increase or decrease?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Key drivers",
        "quote": "contact rate (beta), recruitment rate (Lambda), the loss of protection for the vaccination rate (theta), and rate of progression from the exposed class to the infectious class (gamma) were the most important factors."
      },
      "carryForward": "We now explore how natural death influences the burden."
    },
    {
      "kind": "method",
      "finding": 4,
      "title": "Higher death reduces TB load",
      "goal": "Illustrate that increasing natural death lowers infectious numbers.",
      "control": {
        "parameter": "mu",
        "label": "Natural death rate",
        "lowEnd": "0.01",
        "highEnd": "0.03"
      },
      "watch": "Infectious at t=38 (i)",
      "whatIf": {
        "prompt": "What if the natural death rate is doubled?",
        "parameter": "mu",
        "value": 0.0314
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 38,
        "time": 38,
        "relation": "lower",
        "by": 1130000
      },
      "effect": "Doubling the natural death rate reduces infectious count at year 38 by about 1.1 million.",
      "prediction": {
        "prompt": "Will the infectious count at year 38 be higher or lower?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Negative sensitivity",
        "quote": "Parameters with negative sensitivity indices (mu, pi, delta, tau) have the effect of lowering the community's TB burden if their values increases"
      },
      "carryForward": "Finally we compare a scenario with no change to see the baseline."
    },
    {
      "kind": "result",
      "finding": null,
      "title": "Baseline world",
      "goal": "Provide the reference trajectory without any parameter change.",
      "control": {
        "parameter": "beta",
        "label": "Contact rate (unchanged)",
        "lowEnd": "7.75e-7",
        "highEnd": "7.75e-7"
      },
      "watch": "Infectious peak (i)",
      "whatIf": {
        "prompt": "No change; keep all parameters at baseline.",
        "parameter": "beta",
        "value": 7.75e-7
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 38,
        "relation": "higher",
        "by": 0
      },
      "effect": "The baseline world matches the original model.",
      "prediction": {
        "prompt": "What is the infectious peak compared to itself?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": null,
      "carryForward": "End of the game."
    }
  ],
  "limits": [
    "Compare peaks on the same chart.",
    "Predict before the what‑if runs."
  ]
}
